export default JSON.parse(
  "{\n  \"workId\": \"mo-zi\",\n  \"chapter\": {\n    \"id\": \"mo-zi_ch-25\",\n    \"workId\": \"mo-zi\",\n    \"order\": 25,\n    \"title\": \"節葬下\",\n    \"difficulty\": 5,\n    \"estimatedMinutes\": 14,\n    \"passageIds\": [\n      \"mo-zi_ch-25_p-1\",\n      \"mo-zi_ch-25_p-2\",\n      \"mo-zi_ch-25_p-3\",\n      \"mo-zi_ch-25_p-4\",\n      \"mo-zi_ch-25_p-5\",\n      \"mo-zi_ch-25_p-6\",\n      \"mo-zi_ch-25_p-7\",\n      \"mo-zi_ch-25_p-8\",\n      \"mo-zi_ch-25_p-9\",\n      \"mo-zi_ch-25_p-10\",\n      \"mo-zi_ch-25_p-11\",\n      \"mo-zi_ch-25_p-12\",\n      \"mo-zi_ch-25_p-13\"\n    ],\n    \"tags\": [\n      \"墨家\",\n      \"墨子\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"mo-zi_ch-25_p-1\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子言曰：「仁者之為天下度也，闢之無以異乎孝子之為親度也。今孝子之為親度也，將柰何哉？曰：『親貧則從事乎富之，人民寡則從事乎眾之，眾亂則從事乎治之。』當其於此也，亦有力不足，財不贍，智不智，然後己矣。無敢舍餘力，隱謀遺利，而不為親為之者矣。若三務者，孝子之為親度也，既若此矣。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-1_s-1\",\n        \"mo-zi_ch-25_p-1_s-2\",\n        \"mo-zi_ch-25_p-1_s-3\",\n        \"mo-zi_ch-25_p-1_s-4\",\n        \"mo-zi_ch-25_p-1_s-5\",\n        \"mo-zi_ch-25_p-1_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"子墨子說道：仁的人的為天下度啊，闢的無以異乎孝子的為親度啊。今孝子的為親度啊，將柰何哉？說道：親貧則從事乎富的，人民寡則從事乎眾的，眾亂則從事乎治的。當他的於此啊，亦有力不足，財不贍，智不智，然後己矣。無敢舍餘力，隱謀遺利，而且不為親為的的人矣。若三務的人，孝子的為親度啊，既若此矣。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「子墨子言曰：「仁者之為天下度也，闢之無以異乎孝子之為親度也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「言」、「仁」、「為」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「子墨子言曰仁者之為天下度也闢之無以異乎孝子之為親」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「今孝子之為親度也，將柰何哉」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-2\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 2,\n      \"canonicalText\": \"雖仁者之為天下度，亦猶此也。曰：『天下貧則從事乎富之，人民寡則從事乎眾之，眾而亂則從事乎治之。』當其於此，亦有力不足，財不贍、智不智，然後已矣。無敢舍餘力，隱謀遺利，而不為天下為之者矣。若三務者，此仁者之為天下度也，既若此矣。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-2_s-1\",\n        \"mo-zi_ch-25_p-2_s-2\",\n        \"mo-zi_ch-25_p-2_s-3\",\n        \"mo-zi_ch-25_p-2_s-4\",\n        \"mo-zi_ch-25_p-2_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"雖仁的人的為天下度，亦猶此啊。說道：天下貧則從事乎富的，人民寡則從事乎眾的，眾而且亂則從事乎治的。當他的於此，亦有力不足，財不贍、智不智，然後已矣。無敢舍餘力，隱謀遺利，而且不為天下為的的人矣。若三務的人，此仁的人的為天下度啊，既若此矣。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「雖仁者之為天下度，亦猶此也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「仁」、「為」、「天」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「雖仁者之為天下度亦猶此也曰天下貧則從事乎富之人民」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「曰：『天下貧則從事乎富之，人民寡則從事乎眾之，眾而亂則從事乎治之」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 3,\n      \"canonicalText\": \"今逮至昔者三代聖王既沒，天下失義，後世之君子，或以厚葬久喪以為仁也，義也，孝子之事也；或以厚葬久喪以為非仁義，非孝子之事也。曰二子者，言則相非，行即相反，皆曰：『吾上祖述堯舜禹湯文武之道者也。』而言即相非，行即相反，於此乎後世之君子，皆疑惑乎二子者言也。若苟疑惑乎之二子者言，然則姑嘗傳而為政乎國家萬民而觀之。計厚葬久喪，奚當此三利者？我意若使法其言，用其謀，厚葬久喪實可以富貧眾寡，定危治亂乎，此仁也，義也，孝子之事也，為人謀者不可不勸也。仁者將興之天下，誰賈而使民譽之，終勿廢也。意亦使法其言，用其謀，厚葬久喪實不可以富貧眾寡，定危理亂乎，此非仁非義，非孝子之事也，為人謀者不可不沮也。仁者將求除之天下，相廢而使人非之，終身勿為。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-3_s-1\",\n        \"mo-zi_ch-25_p-3_s-2\",\n        \"mo-zi_ch-25_p-3_s-3\",\n        \"mo-zi_ch-25_p-3_s-4\",\n        \"mo-zi_ch-25_p-3_s-5\",\n        \"mo-zi_ch-25_p-3_s-6\",\n        \"mo-zi_ch-25_p-3_s-7\",\n        \"mo-zi_ch-25_p-3_s-8\",\n        \"mo-zi_ch-25_p-3_s-9\",\n        \"mo-zi_ch-25_p-3_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今逮至昔日三代聖王既沒，天下失義，後世的君子，或以厚葬久喪以為仁啊，義啊，孝子的事啊；或以厚葬久喪以為絕不是仁義，絕不是孝子的事啊。說道：二子的人，言則相絕不是，行即相反，皆說道：吾上祖述堯舜禹湯文武的道的人啊。而且言即相絕不是，行即相反，於此乎後世的君子，皆疑惑乎二子的人言啊。若苟疑惑乎的二子的人言，然則姑嘗傳而且為政乎國家萬民而且觀的。計厚葬久喪，奚當此三利的人？我意若使法他的言，用他的謀，厚葬久喪客觀實體可以富貧眾寡，定危治亂乎，此仁啊，義啊，孝子的事啊，為人謀的人不可不勸啊。仁的人將興的天下，誰賈而且使民譽的，終勿廢啊。意亦使法他的言，用他的謀，厚葬久喪客觀實體不可以富貧眾寡，定危理亂乎，此絕不是仁絕不是義，絕不是孝子的事啊，為人謀的人不可不沮啊。仁的人將求除的天下，相廢而且使人絕不是的，終身勿為。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「今逮至昔者三代聖王既沒，天下失義，後世之君子，或以厚葬久喪以為仁也，義也，孝子之事也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「逮」、「至」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今逮至昔者三代聖王既沒天下失義後世之君子或以厚葬」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「或以厚葬久喪以為非仁義，非孝子之事也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 4,\n      \"canonicalText\": \"且故興天下之利，除天下之害，令國家百姓之不治也，自古及今，未嘗之有也。何以知其然也？今天下之士君子，將猶多皆疑惑厚葬久喪之為中是非利害也。」故子墨子言曰：「然則姑嘗稽之，今雖毋法執厚葬久喪者言，以為事乎國家。此存乎王公大人有喪者，曰棺槨必重，葬埋必厚，衣衾必多，文繡必繁，丘隴必巨；存乎匹夫賤人死者，殆竭家室；乎諸侯死者，虛車府，然後金玉珠璣比乎身，綸組節約，車馬藏乎壙，又必多為屋幕。鼎鼓幾梴壺濫，戈劍羽旄齒革，挾而埋之，滿意。若送從，曰天子殺殉，眾者數百，寡者數十。將軍大夫殺殉，眾者數十，寡者數人。處喪之法將柰何哉？曰哭泣不秩聲翁，縗絰垂涕，處倚廬，寢苫枕塊，又相率強不食而為飢，薄衣而為寒，使面目陷陬，顏色黧黑耳目不聰明，手足不勁強，不可用也。又曰上士之操喪也，必扶而能起，杖而能行，以此共三年。若法若言，行若道使王公大人行此，則必不能蚤朝，五官六府，闢草木，實倉廩。使農夫行此。則必不能蚤出夜入，耕稼樹藝。使百工行此，則必不能修舟車為器皿矣。使婦人行此，則必不能夙興夜寐，紡績織紝。細計厚葬。為多埋賦之財者也。計久喪，為久禁從事者也。財以成者，扶而埋之；後得生者，而久禁之，以此求富，此譬猶禁耕而求穫也，富之說無可得焉。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-4_s-1\",\n        \"mo-zi_ch-25_p-4_s-2\",\n        \"mo-zi_ch-25_p-4_s-3\",\n        \"mo-zi_ch-25_p-4_s-4\",\n        \"mo-zi_ch-25_p-4_s-5\",\n        \"mo-zi_ch-25_p-4_s-6\",\n        \"mo-zi_ch-25_p-4_s-7\",\n        \"mo-zi_ch-25_p-4_s-8\",\n        \"mo-zi_ch-25_p-4_s-9\",\n        \"mo-zi_ch-25_p-4_s-10\",\n        \"mo-zi_ch-25_p-4_s-11\",\n        \"mo-zi_ch-25_p-4_s-12\",\n        \"mo-zi_ch-25_p-4_s-13\",\n        \"mo-zi_ch-25_p-4_s-14\",\n        \"mo-zi_ch-25_p-4_s-15\",\n        \"mo-zi_ch-25_p-4_s-16\",\n        \"mo-zi_ch-25_p-4_s-17\",\n        \"mo-zi_ch-25_p-4_s-18\",\n        \"mo-zi_ch-25_p-4_s-19\",\n        \"mo-zi_ch-25_p-4_s-20\",\n        \"mo-zi_ch-25_p-4_s-21\",\n        \"mo-zi_ch-25_p-4_s-22\",\n        \"mo-zi_ch-25_p-4_s-23\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"況且一心想為天下興起利益、掃除禍害，卻導致國家混亂、百姓貧窮難治的，自古至今從未有過這種道理。憑什麼知道是這樣呢？當今天下的士人君子，如果內心真想行仁義之政、求做崇高士人，對上切合聖王治道，對下契合萬民利益，就不可不詳察厚葬久喪對國家的危害。厚葬久喪之說主張：棺槨必須層層重疊，隨葬器物必須極其豐厚，衣衾被褥必須大量陪葬，墓穴必須廣大深峻，墳塚宛如山丘。平民身死往往耗盡家產，諸侯身死甚至竭盡國庫，殉葬之人多達數十乃至數百。居喪守孝者必須哭泣無常，身穿粗麻重孝，居於倚廬，睡在草墊枕著土塊，強忍飢餓，面容枯槁憔悴，扶杖方能站起。如此居喪三年之久，身心殘毀，無法從事農桑生產，百官無法處理政務，兵士無法操練守備。這不但無法富國，反而使國家極度貧困；無法繁衍人口，反而使民眾夭折減少；無法穩定治安，反而使法度崩潰動亂。企圖藉此治國，豈非南轅北轍！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「且故興天下之利，除天下之害，令國家百姓之不治也，自古及今，未嘗之有也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「且」、「興」、「天」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「且故興天下之利除天下之害令國家百姓之不治也自古及」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「何以知其然也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 5,\n      \"canonicalText\": \"是故求以富家而既已不可矣，欲以眾人民，意者可邪？其說又不可矣。今唯無以厚葬久喪者為政，君死，喪之三年；父母死，喪之三年；妻與後子死者，五皆喪之三年；然後伯父叔父兄弟孽子其；族人五月；姑姊甥舅皆有月數。則毀瘠必有制矣，使面目陷陬，顏色黧黑，耳目不聰明，手足不勁強，不可用也。又曰上士操喪也，必扶而能起，杖而能行，以此共三年。若法若言，行若道，苟其飢約，又若此矣，是故百姓冬不仞寒，夏不仞暑，作疾病死者，不可勝計也。此其為敗男女之交多矣。以此求眾，譬猶使人負劍，而求其壽也。眾之說無可得焉。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-5_s-1\",\n        \"mo-zi_ch-25_p-5_s-2\",\n        \"mo-zi_ch-25_p-5_s-3\",\n        \"mo-zi_ch-25_p-5_s-4\",\n        \"mo-zi_ch-25_p-5_s-5\",\n        \"mo-zi_ch-25_p-5_s-6\",\n        \"mo-zi_ch-25_p-5_s-7\",\n        \"mo-zi_ch-25_p-5_s-8\",\n        \"mo-zi_ch-25_p-5_s-9\",\n        \"mo-zi_ch-25_p-5_s-10\",\n        \"mo-zi_ch-25_p-5_s-11\",\n        \"mo-zi_ch-25_p-5_s-12\",\n        \"mo-zi_ch-25_p-5_s-13\",\n        \"mo-zi_ch-25_p-5_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"正因為如此求以富家而且既已不可矣，欲以眾人民，意的人可邪？他的推理說理又不可矣。今唯無以厚葬久喪的人為政，君死，喪的三年；父母死，喪的三年；妻與後子死的人，五皆喪的三年；然後伯父叔父兄弟孽子他的；族人五月；姑姊甥舅皆有月數。則毀瘠必有制矣，使面目陷陬，顏色黧黑，耳目不聰明，手足不勁強，不可用啊。又說道：上士操喪啊，必扶而且能起，杖而且能行，以此共三年。若法若言，行若道，苟他的飢約，又若此矣，正因為如此百姓冬不仞寒，夏不仞暑，作疾病死的人，不可勝計啊。此他的為敗男女的交多矣。以此求眾，譬猶使人負劍，而且求他的壽啊。眾的推理說理無可得焉。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「是故求以富家而既已不可矣，欲以眾人民，意者可邪」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「是」、「求」、「富」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「是故求以富家而既已不可矣欲以眾人民意者可邪其說又」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「其說又不可矣」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 6,\n      \"canonicalText\": \"是故求以眾人民，而既以不可矣，欲以治刑政，意者可乎？其說又不可矣。今唯無以厚葬久喪者為政，國家必貧，人民必寡，刑政必亂。若法若言，行若道，使為上者行此，則不能聽治；使為下者行此，則不能從事。上不聽治，刑政必亂；下不行從事，衣食之財必不足。若苟不足，為人弟者，求其兄而不得不弟弟必將怨其兄矣；為人子者，求其親而不得，不孝子必是怨其親矣；為人臣者，求之君而不得，不忠臣必且亂其上矣。是以僻淫邪行之民，出則無衣也，入則無食也，內續奚吾，並為淫暴，而不可勝禁也。是故盜賊眾而治者寡。夫眾盜賊而寡治者，以此求治，譬猶使人三還而毋負己也，治之說無可得焉。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-6_s-1\",\n        \"mo-zi_ch-25_p-6_s-2\",\n        \"mo-zi_ch-25_p-6_s-3\",\n        \"mo-zi_ch-25_p-6_s-4\",\n        \"mo-zi_ch-25_p-6_s-5\",\n        \"mo-zi_ch-25_p-6_s-6\",\n        \"mo-zi_ch-25_p-6_s-7\",\n        \"mo-zi_ch-25_p-6_s-8\",\n        \"mo-zi_ch-25_p-6_s-9\",\n        \"mo-zi_ch-25_p-6_s-10\",\n        \"mo-zi_ch-25_p-6_s-11\",\n        \"mo-zi_ch-25_p-6_s-12\",\n        \"mo-zi_ch-25_p-6_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"因此，希求透過厚葬久喪來使國家人口眾多，已經證明是行不通的了；那麼想藉由厚葬久喪來嚴明刑賞、整飭政務，難道就能行得通嗎？這種說法同樣是行不通的。如今若以提倡厚葬久喪之道來推行政事，國家必定陷入極度貧窮，百姓人口必定日益凋零，而官府的刑政法度必定陷於紊亂廢弛。貧窮則無法備辦潔淨豐富的祭品祭祀天帝鬼神；人口稀少則缺乏兵丁拱衛疆土；刑政紊亂則內無賞罰綱紀，外難禦侮抗敵。官吏疲於居喪廢弛公務，農夫荒廢田疇顆粒無收，盜賊蜂起而刑獄無法斷決。因此指望藉厚葬久喪來使刑政清明，完全是背道而馳。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「是故求以眾人民，而既以不可矣，欲以治刑政，意者可乎」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「是」、「求」、「眾」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「是故求以眾人民而既以不可矣欲以治刑政意者可乎其說」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「其說又不可矣」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 7,\n      \"canonicalText\": \"是故求以治刑政，而既已不可矣，欲以禁止大國之攻小國也，意者可邪？其說又不可矣。是故昔者聖王既沒，天下失義，諸侯力征。南有楚、越之王，而北有齊、晉之君，此皆砥礪其卒伍，以攻伐併兼為政於天下。是故凡大國之所以不攻小國者，積委多，城郭修，上下調和，是故大國不耆攻之，無積委，城郭不修，上下不調和，是故大國耆攻之。今唯無以厚葬久喪者為政，國家必貧，人民必寡，刑政必亂。若苟貧，是無以為積委也；若苟寡，是城郭溝渠者寡也；若苟亂，是出戰不克，入守不固。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-7_s-1\",\n        \"mo-zi_ch-25_p-7_s-2\",\n        \"mo-zi_ch-25_p-7_s-3\",\n        \"mo-zi_ch-25_p-7_s-4\",\n        \"mo-zi_ch-25_p-7_s-5\",\n        \"mo-zi_ch-25_p-7_s-6\",\n        \"mo-zi_ch-25_p-7_s-7\",\n        \"mo-zi_ch-25_p-7_s-8\",\n        \"mo-zi_ch-25_p-7_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"因此，求藉厚葬久喪來整飭刑政治理，既然已確定行不通；那麼若想以此來制止大國攻伐小國，難道會行得通嗎？這種主張更是絕無可能。自古昔聖王謝世之後，天下逐漸喪失公義，諸侯往往依仗強兵兼併弱小。若國家實行厚葬久喪，國庫空虛、兵甲廢弛、兵員疲弱羸瘦，大國見其孱弱無備，便會大舉興兵侵伐，掠奪其土地、俘虜其人民。指望以自身國力的虛耗與衰竭來乞求強鄰不起侵陵野心，無異於引頸就戮。因此厚葬久喪，絕不能消弭戰爭侵伐。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「是故求以治刑政，而既已不可矣，欲以禁止大國之攻小國也，意者可邪」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「是」、「求」、「治」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「是故求以治刑政而既已不可矣欲以禁止大國之攻小國也」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「其說又不可矣」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 8,\n      \"canonicalText\": \"此求禁止大國之攻小國也，而既已不可矣。欲以幹上帝鬼神之褔，意者可邪？其說又不可矣。今唯無以厚葬久喪者為政，國家必貧，人民必寡，刑政必亂。若苟貧，是粢盛酒醴不淨潔也；若苟寡，是事上帝鬼神者寡也；若苟亂，是祭祀不時度也。今又禁止事上帝鬼神，為政若此，上帝鬼神，始得從上撫之曰：『我有是人也，與無是人也，孰愈？』曰：『我有是人也，與無是人也，無擇也。』則惟上帝鬼神降之罪厲之禍罰而棄之，則豈不亦乃其所哉！\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-8_s-1\",\n        \"mo-zi_ch-25_p-8_s-2\",\n        \"mo-zi_ch-25_p-8_s-3\",\n        \"mo-zi_ch-25_p-8_s-4\",\n        \"mo-zi_ch-25_p-8_s-5\",\n        \"mo-zi_ch-25_p-8_s-6\",\n        \"mo-zi_ch-25_p-8_s-7\",\n        \"mo-zi_ch-25_p-8_s-8\",\n        \"mo-zi_ch-25_p-8_s-9\",\n        \"mo-zi_ch-25_p-8_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"此求禁止大國的攻小國啊，而且既已不可矣。欲以幹上帝鬼神的褔，意的人可邪？他的推理說理又不可矣。今唯無以厚葬久喪的人為政，國家必貧，人民必寡，刑政必亂。若苟貧，是粢盛酒醴不淨潔啊；若苟寡，是事上帝鬼神的人寡啊；若苟亂，是祭祀不時度啊。今又禁止事上帝鬼神，為政若此，上帝鬼神，始得從上撫說道：我有是人啊，與無是人啊，孰愈？說道：我有是人啊，與無是人啊，無擇啊。則惟上帝鬼神降的罪厲的禍罰而且棄的，則豈不亦乃他的所哉！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「此求禁止大國之攻小國也，而既已不可矣」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「求」、「禁」、「止」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「此求禁止大國之攻小國也而既已不可矣欲以幹上帝鬼神」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「欲以幹上帝鬼神之褔，意者可邪」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-9\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 9,\n      \"canonicalText\": \"故古聖王制為葬埋之法，曰：『棺三寸，足以朽體；衣衾三領，足以覆惡。以及其葬也，下毋及泉，上毋通臭，壟若參耕之畝，則止矣。死則既以葬矣，生者必無久哭，而疾而從事，人為其所能，以交相利也。』此聖王之法也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-9_s-1\",\n        \"mo-zi_ch-25_p-9_s-2\",\n        \"mo-zi_ch-25_p-9_s-3\",\n        \"mo-zi_ch-25_p-9_s-4\",\n        \"mo-zi_ch-25_p-9_s-5\",\n        \"mo-zi_ch-25_p-9_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以古聖王制為葬埋的法，說道：棺三寸，足以朽體；衣衾三領，足以覆惡。以及他的葬啊，下毋及泉，上毋通臭，壟若參耕的畝，則止矣。死則既以葬矣，生的人必無久哭，而且疾而且從事，人為他的所能，以交相利啊。此聖王的法啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「故古聖王制為葬埋之法，曰：『棺三寸，足以朽體」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「古」、「聖」、「王」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「故古聖王制為葬埋之法曰棺三寸足以朽體衣衾三領足以」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「衣衾三領，足以覆惡」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 10,\n      \"canonicalText\": \"今執厚葬久喪者之言曰：「厚葬久喪雖使不可以富貧眾寡，定危治亂，然此聖王之道也。」子墨子曰：「不然。昔者堯北教乎八狄，道死，葬蛩山之陰，衣衾三領，榖木之棺，葛以緘之，既窆而後哭，滿埳無封。已葬，而牛馬乘之。舜西教乎七戎，道死，葬南己之市，衣衾三領，榖木之棺，葛以緘之，已葬，而市人乘之。禹東教乎九夷，道死，葬會稽之山，衣衾三領，桐棺三寸，葛以緘之，絞之不合，通之不埳，土地之深，下毋及泉，上毋通臭。既葬，收餘壤其上，壟若參耕之畝，則止矣。若以此若三聖王者觀之，則厚葬久喪果非聖王之道。故三王者，皆貴為天子，富有天下，豈憂財用之不足哉？以為如此葬埋之法。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-10_s-1\",\n        \"mo-zi_ch-25_p-10_s-2\",\n        \"mo-zi_ch-25_p-10_s-3\",\n        \"mo-zi_ch-25_p-10_s-4\",\n        \"mo-zi_ch-25_p-10_s-5\",\n        \"mo-zi_ch-25_p-10_s-6\",\n        \"mo-zi_ch-25_p-10_s-7\",\n        \"mo-zi_ch-25_p-10_s-8\",\n        \"mo-zi_ch-25_p-10_s-9\",\n        \"mo-zi_ch-25_p-10_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"如今堅持厚葬久喪的人辯解說：「厚葬久喪縱然不能使貧窮轉為富裕、人口由少增多、安定危難治理動亂，然而這終究是古代聖王傳下來的成法制度啊。」墨子說：「絕非如此！昔日三代聖王根本不曾推行厚葬久喪。昔日堯帝向北方巡視教化八狄部落，在途中逝世，便就地安葬在蛩蛩山，只用三件粗衣裹身，薄木為棺，葛藤束棺，墓穴掘深剛好掩蓋棺木，不封土堆墳，哭泣哀悼後隨即返回各自勞作；舜帝向南方巡行教化七戎部落，在途中逝世，就地安葬在蒼梧之野，衣衾不改，棺木甚薄，不起墳塚；大禹向東方教化九夷，死於途中，就地安葬在會稽山上，棺木厚僅三寸，衣被僅備三領，掘土不穿地下泉脈，斂葬完畢即平復地面。此三位至聖之王皆親身示範節葬，何曾有厚葬久喪之法？」\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「今執厚葬久喪者之言曰：「厚葬久喪雖使不可以富貧眾寡，定危治亂，然此聖王之道也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「執」、「厚」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今執厚葬久喪者之言曰厚葬久喪雖使不可以富貧眾寡定」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「」子墨子曰：「不然」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 11,\n      \"canonicalText\": \"今王公大人之為葬埋，則異於此。必大棺中棺，革闠三操，璧玉即具，戈劍鼎鼓壺濫，文繡素練，大鞅萬領，輿馬女樂皆具，曰必捶塗差通，壟雖凡山陵。此為輟民之事，靡民之財，不可勝計也，其為毋用若此矣。」是故子墨子曰：「鄉者，吾本言曰，意亦使法其言，用其謀，計厚葬久喪，請可以富貧眾寡，定危治亂乎，則仁也，義也，孝子之事也，為人謀者，不可不勸也；意亦使法其言，用其謀，若人厚葬久喪，實不可以富貧眾寡，定危治亂乎，則非仁也，非義也，非孝子之事也，為人謀者，不可不沮也。是故求以富國家，甚得貧焉；欲以眾人民，甚得寡焉；欲以治刑政，甚得亂焉；求以禁止大國之攻小國也，而既已不可矣；欲以幹上帝鬼神之福，又得禍焉。上稽之堯舜禹湯文武之道而政逆之，下稽之桀紂幽厲之事，猶合節也。若以此觀，則厚葬久喪其非聖王之道也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-11_s-1\",\n        \"mo-zi_ch-25_p-11_s-2\",\n        \"mo-zi_ch-25_p-11_s-3\",\n        \"mo-zi_ch-25_p-11_s-4\",\n        \"mo-zi_ch-25_p-11_s-5\",\n        \"mo-zi_ch-25_p-11_s-6\",\n        \"mo-zi_ch-25_p-11_s-7\",\n        \"mo-zi_ch-25_p-11_s-8\",\n        \"mo-zi_ch-25_p-11_s-9\",\n        \"mo-zi_ch-25_p-11_s-10\",\n        \"mo-zi_ch-25_p-11_s-11\",\n        \"mo-zi_ch-25_p-11_s-12\",\n        \"mo-zi_ch-25_p-11_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"如今王公貴族大人辦理喪葬，則與古代聖王的儉樸準則完全相異。棺木務必使用巨大的重棺與套棺，以皮革圍飾並束以多重重帶，玉璧珠翠隨葬周備，戈矛長劍、鼎俎鐘鼓、酒壺水鑑一應俱全，文繡絲綢、錦緞被褥堆積萬件，車馬器玩深埋墓室，又驅使眾多活人生殉。送葬隊伍連綿百里，修築巨塚如同丘陵，耗盡國家財力、殺戮無辜百姓。這等耗竭生民膏血、殘害無辜生命的惡行，卻妄稱是追念先人的孝道，這實在是天理不容的重罪！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「今王公大人之為葬埋，則異於此」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「王」、「公」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今王公大人之為葬埋則異於此必大棺中棺革闠三操璧玉」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「必大棺中棺，革闠三操，璧玉即具，戈劍鼎鼓壺濫，文繡素練，大鞅萬領，輿馬女樂皆具，曰必捶塗差通，壟雖凡山陵」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 12,\n      \"canonicalText\": \"今執厚葬久喪者言曰：「厚葬久喪，果非聖王之道，夫胡說中國之君子，為而不已，操而不擇哉？」子墨子曰：「此所謂便其習而義其俗者也。昔者越之東有輆沐之國者，其長子生，則解而食之。謂之『宜弟』；其大父死，負其大母而棄之，曰鬼妻不可與居處。此上以為政，下以為俗，為而不已，操而不擇，則此豈實仁義之道哉？此所謂便其習而義其俗者也。楚之南有炎人國者，其親戚死朽其肉而棄之，然後埋其骨，乃成為孝子。秦之西有儀渠之國者，其親戚死，聚柴薪而焚之，燻上，謂之登遐，然後成為孝子。此上以為政，下以為俗，為而不已，操而不擇，則此豈實仁義之道哉？此所謂便其習而義其俗者也。若以此若三國者觀之，則亦猶薄矣。若以中國之君子觀之，則亦猶厚矣。如彼則大厚，如此則大薄，然則葬埋之有節矣。故衣食者，人之生利也，然且猶尚有節；葬埋者，人之死利也，夫何獨無節於此乎。子墨子制為葬埋之法曰：「棺三寸，足以朽骨；衣三領，足以朽肉；掘地之深，下無菹漏，氣無發洩於上，壟足以期其所，則止矣。哭往哭來，反從事乎衣食之財，佴乎祭祀，以致孝於親。故曰子墨子之法，不失死生之利者，此也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-12_s-1\",\n        \"mo-zi_ch-25_p-12_s-2\",\n        \"mo-zi_ch-25_p-12_s-3\",\n        \"mo-zi_ch-25_p-12_s-4\",\n        \"mo-zi_ch-25_p-12_s-5\",\n        \"mo-zi_ch-25_p-12_s-6\",\n        \"mo-zi_ch-25_p-12_s-7\",\n        \"mo-zi_ch-25_p-12_s-8\",\n        \"mo-zi_ch-25_p-12_s-9\",\n        \"mo-zi_ch-25_p-12_s-10\",\n        \"mo-zi_ch-25_p-12_s-11\",\n        \"mo-zi_ch-25_p-12_s-12\",\n        \"mo-zi_ch-25_p-12_s-13\",\n        \"mo-zi_ch-25_p-12_s-14\",\n        \"mo-zi_ch-25_p-12_s-15\",\n        \"mo-zi_ch-25_p-12_s-16\",\n        \"mo-zi_ch-25_p-12_s-17\",\n        \"mo-zi_ch-25_p-12_s-18\",\n        \"mo-zi_ch-25_p-12_s-19\",\n        \"mo-zi_ch-25_p-12_s-20\",\n        \"mo-zi_ch-25_p-12_s-21\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"如今主張厚葬久喪的人說：厚葬久喪如果真的不是聖王的治國之道，那為什麼中原的君子們，一直這樣做而不停止，堅持遵守而不願改變呢？墨子說：這就是所謂的習慣成自然，把風俗當成了真理。從前越國以東有個叫輆沐的國家，他們生下第一個兒子，就將他肢解喫掉，稱之為宜弟（對弟弟有利）；祖父死後，就把祖母揹出去拋棄，說不能和鬼的妻子住在一起。上面把這當作政策，下面把這當作風俗，一直這樣做而不停止，堅持遵守而不願改變，難道這真的是仁義之道嗎？這就是習慣成自然，把風俗當成真理。楚國以南有個炎人國，父母親戚死後，要等肉體腐爛拋棄，只埋葬骨頭，這樣纔算是孝子。秦國以西有個儀渠國，親戚死後，要堆積木柴焚燒，讓煙氣上升，稱為登遐（昇天），這樣纔算孝子。這些地方都把這種事當作政策和風俗，一直這樣做而不停止，這難道真的是仁義之道嗎？這就是習慣成自然。如果用這三國的風俗來看，就顯得太刻薄了；如果用中原君子的做法來看，又顯得太豐厚了。像他們那樣太過刻薄，像中原這樣太過豐厚，所以喪葬應該有一個適當的節度。衣食是生者的利益，尚且需要節制；喪葬是處理死者的事，怎麼能獨獨不加節制呢？所以墨子制定的喪葬法則說：棺木三寸厚，足以朽化骨骸；壽衣三件，足以朽化肉體；墓穴挖深，只要下面不漏水，上面不散發屍氣，墳丘足夠標記位置就可以了。哭著送葬，哭著回來，回來後就繼續從事生產衣食財富的工作，按時祭祀，以表達對父母的孝心。所以說，墨子的法則，既不損害生者的利益，又兼顧死者，這就是原因。\",\n        \"analysis\": \"【訓詁與名物】「便其習而義其俗」意指習慣於某種作法，便將該風俗視為合乎道義。「大父」「大母」即祖父、祖母。「登遐」指昇天，古人認為焚屍能使靈魂昇天。「佴」同「貳」，引申為相繼、按時。「菹漏」指低窪積水漏水之處。\\\\n【章法與結構】本段採用了先破後立的論證結構。首先引述反對者的觀點，接著連舉輆沐、炎人、儀渠三個邊遠國家的奇異喪葬風俗，透過極端反例來打破「存在即合理、風俗即真理」的迷思；接著批評中原的厚葬與夷狄的薄葬皆走極端；最後提出墨家「葬埋有節」的具體標準，邏輯嚴密，層次分明。\\\\n【思想與義理】此段反映了墨家「節葬」的核心主張，並展現了墨子跳脫文化本位主義的宏觀視角。他批判儒家以傳統風俗為絕對真理的保守態度，強調不應盲目遵從習俗，而應以「是否有利於生者與死者」的實用主義原則作為檢驗標準。墨子提倡簡樸的喪葬制度，旨在減輕百姓的經濟負擔，體現了強烈的平民關懷與務實精神。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-13\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"order\": 13,\n      \"canonicalText\": \"故子墨子言曰：「今天下之士君子，中請將欲為仁義，求為上士，上欲中聖王之道，下欲中國家百姓之利，故當若節喪之為政，而不可不察此者也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-25_p-13_s-1\",\n        \"mo-zi_ch-25_p-13_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以子墨子說道：今天下的士君子，中請將欲為仁義，求為上士，上欲中聖王的道，下欲中國家百姓的利，所以當若節喪的為政，而且不可不察此的人啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈節葬下〉。墨子學派以兼愛天下為宗，開篇「故子墨子言曰：「今天下之士君子，中請將欲為仁義，求為上士，上欲中聖王之道，下欲中國家百姓之利，故當若節喪之為政，而不可不察此者也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「言」、「今」、「天」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「故子墨子言曰今天下之士君子中請將欲為仁義求為上士」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「故子墨子言曰：「今天下之士君子，中請將欲為仁義，求為上士，上欲中聖王之道，下欲中國家百姓之利，故當若節喪之為政，而不可不察此者也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"mo-zi_ch-25_p-1_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子言曰：「仁者之為天下度也，闢之無以異乎孝子之為親度也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-1_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"今孝子之為親度也，將柰何哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-1_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"曰：『親貧則從事乎富之，人民寡則從事乎眾之，眾亂則從事乎治之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-1_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"』當其於此也，亦有力不足，財不贍，智不智，然後己矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-1_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"無敢舍餘力，隱謀遺利，而不為親為之者矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-1_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"若三務者，孝子之為親度也，既若此矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-2_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"雖仁者之為天下度，亦猶此也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-2_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"曰：『天下貧則從事乎富之，人民寡則從事乎眾之，眾而亂則從事乎治之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-2_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"』當其於此，亦有力不足，財不贍、智不智，然後已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-2_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"無敢舍餘力，隱謀遺利，而不為天下為之者矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-2_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"若三務者，此仁者之為天下度也，既若此矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"今逮至昔者三代聖王既沒，天下失義，後世之君子，或以厚葬久喪以為仁也，義也，孝子之事也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"或以厚葬久喪以為非仁義，非孝子之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"曰二子者，言則相非，行即相反，皆曰：『吾上祖述堯舜禹湯文武之道者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"』而言即相非，行即相反，於此乎後世之君子，皆疑惑乎二子者言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"若苟疑惑乎之二子者言，然則姑嘗傳而為政乎國家萬民而觀之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"計厚葬久喪，奚當此三利者？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"我意若使法其言，用其謀，厚葬久喪實可以富貧眾寡，定危治亂乎，此仁也，義也，孝子之事也，為人謀者不可不勸也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"仁者將興之天下，誰賈而使民譽之，終勿廢也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"意亦使法其言，用其謀，厚葬久喪實不可以富貧眾寡，定危理亂乎，此非仁非義，非孝子之事也，為人謀者不可不沮也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-3_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"仁者將求除之天下，相廢而使人非之，終身勿為。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"且故興天下之利，除天下之害，令國家百姓之不治也，自古及今，未嘗之有也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"何以知其然也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"今天下之士君子，將猶多皆疑惑厚葬久喪之為中是非利害也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"」故子墨子言曰：「然則姑嘗稽之，今雖毋法執厚葬久喪者言，以為事乎國家。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"此存乎王公大人有喪者，曰棺槨必重，葬埋必厚，衣衾必多，文繡必繁，丘隴必巨；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"存乎匹夫賤人死者，殆竭家室；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"乎諸侯死者，虛車府，然後金玉珠璣比乎身，綸組節約，車馬藏乎壙，又必多為屋幕。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"鼎鼓幾梴壺濫，戈劍羽旄齒革，挾而埋之，滿意。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"若送從，曰天子殺殉，眾者數百，寡者數十。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"將軍大夫殺殉，眾者數十，寡者數人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"處喪之法將柰何哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 12,\n      \"canonicalText\": \"曰哭泣不秩聲翁，縗絰垂涕，處倚廬，寢苫枕塊，又相率強不食而為飢，薄衣而為寒，使面目陷陬，顏色黧黑耳目不聰明，手足不勁強，不可用也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 13,\n      \"canonicalText\": \"又曰上士之操喪也，必扶而能起，杖而能行，以此共三年。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 14,\n      \"canonicalText\": \"若法若言，行若道使王公大人行此，則必不能蚤朝，五官六府，闢草木，實倉廩。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 15,\n      \"canonicalText\": \"使農夫行此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 16,\n      \"canonicalText\": \"則必不能蚤出夜入，耕稼樹藝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-17\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 17,\n      \"canonicalText\": \"使百工行此，則必不能修舟車為器皿矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-18\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 18,\n      \"canonicalText\": \"使婦人行此，則必不能夙興夜寐，紡績織紝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-19\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 19,\n      \"canonicalText\": \"細計厚葬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-20\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 20,\n      \"canonicalText\": \"為多埋賦之財者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-21\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 21,\n      \"canonicalText\": \"計久喪，為久禁從事者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-22\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 22,\n      \"canonicalText\": \"財以成者，扶而埋之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-4_s-23\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-4\",\n      \"order\": 23,\n      \"canonicalText\": \"後得生者，而久禁之，以此求富，此譬猶禁耕而求穫也，富之說無可得焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"是故求以富家而既已不可矣，欲以眾人民，意者可邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"其說又不可矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"今唯無以厚葬久喪者為政，君死，喪之三年；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"父母死，喪之三年；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"妻與後子死者，五皆喪之三年；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"然後伯父叔父兄弟孽子其；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"族人五月；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"姑姊甥舅皆有月數。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"則毀瘠必有制矣，使面目陷陬，顏色黧黑，耳目不聰明，手足不勁強，不可用也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"又曰上士操喪也，必扶而能起，杖而能行，以此共三年。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"若法若言，行若道，苟其飢約，又若此矣，是故百姓冬不仞寒，夏不仞暑，作疾病死者，不可勝計也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"此其為敗男女之交多矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"以此求眾，譬猶使人負劍，而求其壽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-5_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-5\",\n      \"order\": 14,\n      \"canonicalText\": \"眾之說無可得焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"是故求以眾人民，而既以不可矣，欲以治刑政，意者可乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"其說又不可矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"今唯無以厚葬久喪者為政，國家必貧，人民必寡，刑政必亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"若法若言，行若道，使為上者行此，則不能聽治；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"使為下者行此，則不能從事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"上不聽治，刑政必亂；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"下不行從事，衣食之財必不足。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"若苟不足，為人弟者，求其兄而不得不弟弟必將怨其兄矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"為人子者，求其親而不得，不孝子必是怨其親矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"為人臣者，求之君而不得，不忠臣必且亂其上矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"是以僻淫邪行之民，出則無衣也，入則無食也，內續奚吾，並為淫暴，而不可勝禁也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"是故盜賊眾而治者寡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-6_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-6\",\n      \"order\": 13,\n      \"canonicalText\": \"夫眾盜賊而寡治者，以此求治，譬猶使人三還而毋負己也，治之說無可得焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"是故求以治刑政，而既已不可矣，欲以禁止大國之攻小國也，意者可邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"其說又不可矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"是故昔者聖王既沒，天下失義，諸侯力征。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"南有楚、越之王，而北有齊、晉之君，此皆砥礪其卒伍，以攻伐併兼為政於天下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"是故凡大國之所以不攻小國者，積委多，城郭修，上下調和，是故大國不耆攻之，無積委，城郭不修，上下不調和，是故大國耆攻之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"今唯無以厚葬久喪者為政，國家必貧，人民必寡，刑政必亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"若苟貧，是無以為積委也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"若苟寡，是城郭溝渠者寡也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-7_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"若苟亂，是出戰不克，入守不固。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"此求禁止大國之攻小國也，而既已不可矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"欲以幹上帝鬼神之褔，意者可邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"其說又不可矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"今唯無以厚葬久喪者為政，國家必貧，人民必寡，刑政必亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"若苟貧，是粢盛酒醴不淨潔也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"若苟寡，是事上帝鬼神者寡也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"若苟亂，是祭祀不時度也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"今又禁止事上帝鬼神，為政若此，上帝鬼神，始得從上撫之曰：『我有是人也，與無是人也，孰愈？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"』曰：『我有是人也，與無是人也，無擇也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-8_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"』則惟上帝鬼神降之罪厲之禍罰而棄之，則豈不亦乃其所哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-9_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"故古聖王制為葬埋之法，曰：『棺三寸，足以朽體；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-9_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"衣衾三領，足以覆惡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-9_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"以及其葬也，下毋及泉，上毋通臭，壟若參耕之畝，則止矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-9_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"死則既以葬矣，生者必無久哭，而疾而從事，人為其所能，以交相利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-9_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"』此聖王之法也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-9_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"今執厚葬久喪者之言曰：「厚葬久喪雖使不可以富貧眾寡，定危治亂，然此聖王之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"」子墨子曰：「不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"昔者堯北教乎八狄，道死，葬蛩山之陰，衣衾三領，榖木之棺，葛以緘之，既窆而後哭，滿埳無封。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"已葬，而牛馬乘之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"舜西教乎七戎，道死，葬南己之市，衣衾三領，榖木之棺，葛以緘之，已葬，而市人乘之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"禹東教乎九夷，道死，葬會稽之山，衣衾三領，桐棺三寸，葛以緘之，絞之不合，通之不埳，土地之深，下毋及泉，上毋通臭。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"既葬，收餘壤其上，壟若參耕之畝，則止矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"若以此若三聖王者觀之，則厚葬久喪果非聖王之道。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"故三王者，皆貴為天子，富有天下，豈憂財用之不足哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-10_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"以為如此葬埋之法。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"今王公大人之為葬埋，則異於此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"必大棺中棺，革闠三操，璧玉即具，戈劍鼎鼓壺濫，文繡素練，大鞅萬領，輿馬女樂皆具，曰必捶塗差通，壟雖凡山陵。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"此為輟民之事，靡民之財，不可勝計也，其為毋用若此矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"」是故子墨子曰：「鄉者，吾本言曰，意亦使法其言，用其謀，計厚葬久喪，請可以富貧眾寡，定危治亂乎，則仁也，義也，孝子之事也，為人謀者，不可不勸也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"意亦使法其言，用其謀，若人厚葬久喪，實不可以富貧眾寡，定危治亂乎，則非仁也，非義也，非孝子之事也，為人謀者，不可不沮也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"是故求以富國家，甚得貧焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 7,\n      \"canonicalText\": \"欲以眾人民，甚得寡焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 8,\n      \"canonicalText\": \"欲以治刑政，甚得亂焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 9,\n      \"canonicalText\": \"求以禁止大國之攻小國也，而既已不可矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 10,\n      \"canonicalText\": \"欲以幹上帝鬼神之福，又得禍焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 11,\n      \"canonicalText\": \"上稽之堯舜禹湯文武之道而政逆之，下稽之桀紂幽厲之事，猶合節也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 12,\n      \"canonicalText\": \"若以此觀，則厚葬久喪其非聖王之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-11_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-11\",\n      \"order\": 13,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"今執厚葬久喪者言曰：「厚葬久喪，果非聖王之道，夫胡說中國之君子，為而不已，操而不擇哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"」子墨子曰：「此所謂便其習而義其俗者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"昔者越之東有輆沐之國者，其長子生，則解而食之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"謂之『宜弟』；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"其大父死，負其大母而棄之，曰鬼妻不可與居處。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"此上以為政，下以為俗，為而不已，操而不擇，則此豈實仁義之道哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"此所謂便其習而義其俗者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"楚之南有炎人國者，其親戚死朽其肉而棄之，然後埋其骨，乃成為孝子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 9,\n      \"canonicalText\": \"秦之西有儀渠之國者，其親戚死，聚柴薪而焚之，燻上，謂之登遐，然後成為孝子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 10,\n      \"canonicalText\": \"此上以為政，下以為俗，為而不已，操而不擇，則此豈實仁義之道哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 11,\n      \"canonicalText\": \"此所謂便其習而義其俗者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 12,\n      \"canonicalText\": \"若以此若三國者觀之，則亦猶薄矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 13,\n      \"canonicalText\": \"若以中國之君子觀之，則亦猶厚矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 14,\n      \"canonicalText\": \"如彼則大厚，如此則大薄，然則葬埋之有節矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 15,\n      \"canonicalText\": \"故衣食者，人之生利也，然且猶尚有節；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 16,\n      \"canonicalText\": \"葬埋者，人之死利也，夫何獨無節於此乎。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-17\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 17,\n      \"canonicalText\": \"子墨子制為葬埋之法曰：「棺三寸，足以朽骨；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-18\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 18,\n      \"canonicalText\": \"衣三領，足以朽肉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-19\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 19,\n      \"canonicalText\": \"掘地之深，下無菹漏，氣無發洩於上，壟足以期其所，則止矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-20\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 20,\n      \"canonicalText\": \"哭往哭來，反從事乎衣食之財，佴乎祭祀，以致孝於親。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-12_s-21\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-12\",\n      \"order\": 21,\n      \"canonicalText\": \"故曰子墨子之法，不失死生之利者，此也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-13_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"故子墨子言曰：「今天下之士君子，中請將欲為仁義，求為上士，上欲中聖王之道，下欲中國家百姓之利，故當若節喪之為政，而不可不察此者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-25_p-13_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-25\",\n      \"passageId\": \"mo-zi_ch-25_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
